    email VARCHAR(254), 
    phone VARCHAR(30), 
    address VARCHAR(255), 
    city VARCHAR(80), 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (customer_id), 
    CONSTRAINT ck_customers_contact_required CHECK (email IS NOT NULL OR phone IS NOT NULL), 
    CONSTRAINT ck_customers_name_not_blank CHECK (length(trim(full_name)) > 0), 
